BEGIN;                                                                                                                                                                                                            
                                                                                                                                                                                                                    
  -- 1. Fix approval_audit_log to match Prompt 2 exactly.                                                                                                                                                           
  -- Safe here because you're still at Prompt 2 and this table should be empty.                                                                                                                                     
  DROP TABLE IF EXISTS approval_audit_log;                                                                                                                                                                          
                                                                                                                                                                                                                    
  CREATE TABLE approval_audit_log (                                                                                                                                                                                 
    id UUID PRIMARY KEY,                                                                                                                                                                                            
    response_id UUID NOT NULL REFERENCES responses(id) ON DELETE CASCADE,                                                                                                                                           
    business_id UUID NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,                                                                                                                                          
    token_hash TEXT NOT NULL,                                                                                                                                                                                       
    device_cookie_hash TEXT,                                                                                                                                                                                        
    action TEXT NOT NULL,                                                                                                                                                                                           
    ip_address TEXT,                                                                                                                                                                                                
    metadata JSONB NOT NULL DEFAULT '{}'::jsonb,                                                                                                                                                                    
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()                                                                                                                                                                   
  );                                                                                                                                                                                                                
                                                                                                                                                                                                                    
  CREATE INDEX idx_aal_response ON approval_audit_log(response_id);                                                                                                                                                 
  CREATE INDEX idx_aal_business ON approval_audit_log(business_id, created_at);                                                                                                                                     
                                                                                                                                                                                                                    
  -- 2. Add the missing businesses indexes.                                                                                                                                                                         
  CREATE INDEX IF NOT EXISTS idx_businesses_sync                                                                                                                                                                    
    ON businesses(subscription_status, last_sync_at)                                                                                                                                                                
    WHERE subscription_status = 'active';                                                                                                                                                                           
                                                                                                                                                                                                                    
  CREATE INDEX IF NOT EXISTS idx_businesses_status                                                                                                                                                                  
    ON businesses(subscription_status);                                                                                                                                                                             
                                                                                                                                                                                                                    
  -- 3. Remove DB-side UUID defaults so inserts must supply app-generated UUIDv7 values.                                                                                                                            
  ALTER TABLE users ALTER COLUMN id DROP DEFAULT;                                                                                                                                                                   
  ALTER TABLE businesses ALTER COLUMN id DROP DEFAULT;                                                                                                                                                              
  ALTER TABLE google_connections ALTER COLUMN id DROP DEFAULT;                                                                                                                                                      
  ALTER TABLE reviews ALTER COLUMN id DROP DEFAULT;                                                                                                                                                                 
  ALTER TABLE responses ALTER COLUMN id DROP DEFAULT;                                                                                                                                                               
  ALTER TABLE approval_links ALTER COLUMN id DROP DEFAULT;                                                                                                                                                          
  ALTER TABLE inbound_events ALTER COLUMN id DROP DEFAULT;                                                                                                                                                          
  ALTER TABLE job_outbox ALTER COLUMN id DROP DEFAULT;                                                                                                                                                              
  ALTER TABLE notification_deliveries ALTER COLUMN id DROP DEFAULT;                                                                                                                                                 
  ALTER TABLE prospect_demos ALTER COLUMN id DROP DEFAULT;                                                                                                                                                          
  ALTER TABLE weekly_summaries ALTER COLUMN id DROP DEFAULT;                                                                                                                                                        
  ALTER TABLE api_costs ALTER COLUMN id DROP DEFAULT;                                                                                                                                                               
  ALTER TABLE review_exceptions ALTER COLUMN id DROP DEFAULT;                                                                                                                                                       
  ALTER TABLE ranking_snapshots ALTER COLUMN id DROP DEFAULT;                                                                                                                                                       
  ALTER TABLE approval_audit_log ALTER COLUMN id DROP DEFAULT;                                                                                                                                                      
                                                                                                                                                                                                                    
  COMMIT;    